mapper.update:
UPDATE turns SET mutation_version=mutation_version+1,updated_at=#{occurredAt},
  cancel_requested_at=#{occurredAt},cancel_reason=#{reason},
  cancel_expected_thread_revision=#{expectedThreadRevision},
  cancel_thread_revision=#{cancelThreadRevision},
  cancel_turn_mutation_version=#{cancelTurnMutationVersion}
WHERE thread_id=#{threadId} AND turn_id=#{turnId}
  AND mutation_version=#{expectedTurnMutationVersion}
  AND state NOT IN ('COMPLETED','FAILED','CANCELLED')
  AND cancel_requested_at IS NULL

UPDATE turns SET state=#{state},mutation_version=mutation_version+1,updated_at=#{occurredAt},completed_at=#{completedAt},terminal_summary=#{summary},
  accepting_inputs=CASE WHEN #{completedAt} IS NULL THEN accepting_inputs ELSE 0 END,
  error_code=#{errorCode},error_message=#{errorMessage}
WHERE thread_id=#{threadId} AND turn_id=#{turnId} AND mutation_version=#{expectedTurnMutationVersion}
  AND state NOT IN ('COMPLETED','FAILED','CANCELLED')

    AND cancel_requested_at IS NULL

UPDATE turns SET mutation_version=mutation_version+1,updated_at=#{occurredAt}
WHERE thread_id=#{threadId} AND turn_id=#{turnId}
  AND mutation_version=#{expectedTurnMutationVersion} AND state=#{state}
  AND state NOT IN ('COMPLETED','FAILED','CANCELLED')
  AND cancel_requested_at IS NOT NULL

mapper.select:
SELECT turn_id,batch_id,call_id,route_kind,local_name,server_id,remote_name,schema_hash,
  route_hash,catalog_revision,access_mode FROM tool_bindings
WHERE turn_id=#{turnId} AND call_id=#{callId}

mapper.update:
UPDATE tools SET state='RUNNING',presentation_json=json_set(presentation_json,'$.status','running'),
  revision=revision+1,updated_at=#{occurredAt}
WHERE turn_id=#{turnId} AND call_id=#{callId} AND state='PREPARED'

mapper.select:
SELECT a.approval_id,a.thread_id,a.turn_id,a.call_id,a.decision,a.expires_at,
  t.state AS turn_state,t.mutation_version
FROM approvals a JOIN turns t ON t.turn_id=a.turn_id WHERE a.approval_id=#{approvalId}

mapper.update:
UPDATE approvals SET decision=#{decision},resolved_at=#{occurredAt}
WHERE turn_id=#{turnId} AND approval_id=#{approvalId} AND call_id=#{callId}
  AND decision IS NULL AND expires_at>=#{occurredAt}

UPDATE tools SET presentation_json=json_set(presentation_json,'$.status','running'),
  revision=revision+1,updated_at=#{occurredAt}
WHERE turn_id=#{turnId} AND call_id=#{callId} AND state='PREPARED'

UPDATE usage SET certainty='KNOWN',input_tokens=#{inputTokens},output_tokens=#{outputTokens},
  total_tokens=#{totalTokens},created_at=#{occurredAt}
WHERE turn_id=#{turnId} AND request_ordinal=#{requestOrdinal} AND request_id=#{requestId}
  AND purpose=#{purpose} AND certainty='UNKNOWN' AND profile_json=#{profileJson}

UPDATE pending_inputs SET kind='STEERING',priority_sequence=#{prioritySequence},
  input_revision=input_revision+1,updated_at=#{occurredAt}
WHERE turn_id=#{turnId} AND input_id=#{inputId} AND state='PENDING'
  AND kind='FOLLOW_UP' AND input_revision=#{expectedInputRevision}

UPDATE pending_inputs SET content_json=#{contentJson},validation_status='PENDING',
  issue_error_code=NULL,issue_message=NULL,issue_retryable=NULL,
  input_revision=input_revision+1,updated_at=#{occurredAt}
WHERE turn_id=#{turnId} AND input_id=#{inputId} AND state='PENDING'
  AND input_revision=#{expectedInputRevision}

UPDATE pending_inputs SET validation_status='NEEDS_ATTENTION',
  issue_error_code=#{errorCode},issue_message=#{message},issue_retryable=#{retryable},
  input_revision=input_revision+1,updated_at=#{occurredAt}
WHERE turn_id=#{turnId} AND input_id=#{inputId} AND state='PENDING'
  AND input_revision=#{expectedInputRevision}
  AND (validation_status!='NEEDS_ATTENTION' OR issue_error_code!=#{errorCode}
    OR issue_message!=#{message} OR issue_retryable!=#{retryable})

UPDATE pending_inputs SET state='CANCELLED',input_revision=input_revision+1,
  updated_at=#{occurredAt},resolved_at=#{occurredAt}
WHERE turn_id=#{turnId} AND input_id=#{inputId} AND state='PENDING'
  AND input_revision=#{expectedInputRevision}

UPDATE pending_inputs SET state='CONSUMED',input_revision=input_revision+1,
  updated_at=#{occurredAt},resolved_at=#{occurredAt}
WHERE input_id=#{inputId} AND state='PENDING' AND input_revision=#{expectedInputRevision}

UPDATE pending_inputs SET state='CANCELLED',input_revision=input_revision+1,
  updated_at=#{occurredAt},resolved_at=#{occurredAt}
WHERE turn_id=#{turnId} AND state='PENDING'

UPDATE turns SET accepting_inputs=0,input_queue_revision=input_queue_revision+1,updated_at=#{occurredAt}
WHERE turn_id=#{turnId} AND input_queue_revision=#{expectedQueueRevision} AND accepting_inputs=1
  AND NOT EXISTS(SELECT 1 FROM pending_inputs p WHERE p.turn_id=#{turnId} AND p.state='PENDING')

UPDATE turns SET mutation_version=mutation_version+1,updated_at=#{occurredAt}
WHERE thread_id=#{threadId} AND turn_id=#{turnId}
  AND mutation_version=#{expectedTurnMutationVersion}
  AND state NOT IN ('COMPLETED','FAILED','CANCELLED')
  AND cancel_requested_at IS NULL
